service-call.in-map:
{workEffortName:workEffortName,
                        purposeEnumId:'WepMeeting', estimatedStartDate:dueDate, estimatedCompletionDate:endDate, assignToPartyId:assignToPartyId,
                        description:description, calendarId:calendarOut?.calendarId}

actions.script:
if (estimatedCompletionDate != null) {
    const isAllDay = allDay === 'Y' || allDay === 'true'
    const start = isAllDay ? ec.l10n.format(estimatedStartDate, 'yyyy-MM-dd') : Number(String(estimatedStartDate))
    const end = isAllDay ? ec.l10n.format(estimatedCompletionDate, 'yyyy-MM-dd') : Number(String(estimatedCompletionDate))
    if (isAllDay ? end < start : end <= start) ec.message.addValidationError(null, 'estimatedCompletionDate', null,
        ec.l10n.localize(isAllDay ? 'The last day must be on or after the start day' : 'The end must be after the start'), null)
}

const myPartyId = ec.user.userAccount?.partyId
attendees = Array.from(new Set((Array.isArray(attendeePartyIds) ? attendeePartyIds : (attendeePartyIds ? String(attendeePartyIds).split(',') : []))
        .map((id) => String(id).trim()).filter((id) => id && id !== myPartyId)))
const startMillis = Number(String(estimatedStartDate))
eventFields = {workEffortName: workEffortName, description: description, calendarId: calendarId, assignToPartyId: myPartyId,
    purposeEnumId: attendees.length ? 'WepMeeting' : null}
if (allDay === 'Y' || allDay === 'true') {
    const endMillis = estimatedCompletionDate != null ? Number(String(estimatedCompletionDate)) : startMillis
    eventFields.allDayStart = ec.l10n.format(String(startMillis), 'yyyy-MM-dd')
    eventFields.allDayEnd = ec.l10n.format(String(endMillis), 'yyyy-MM-dd')
} else {
    eventFields.estimatedStartDate = estimatedStartDate
    eventFields.estimatedCompletionDate = estimatedCompletionDate != null ?
            estimatedCompletionDate : new Date(startMillis + 3600000)
}

// the invitations stand alone: one that fails is logged, the event stays
if (attendees.length) {
    ec.message.pushErrors()
    try {
        ec.service.sync().name('mantle.work.EventServices.send#EventInvitations').parameters({workEffortId: workEffortId,
            partyIdList: attendees, eventUrl: url}).call()
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
    } catch (err) {
        ec.logger.warn(`Event ${workEffortId}: the invitations were not sent: ${err && err.message ? err.message : err}`)
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
}
message = ec.resource.expand('Event created: ${workEffortName}', '', {workEffortName: workEffortName})

then.script:
// the parties mentioned, as the rich text writes them
const ids = []
for (const match of String(noteText).matchAll(/data-mention-id="([^"]+)"/g)) if (!ids.includes(match[1])) ids.push(match[1])
mentionPartyIds = ids
noteContentType = contentType || (/<\/?(p|br|strong|em|ul|ol|li|a|code|span)\b/i.test(String(noteText)) ? 'text/html' : 'text/plain')

service-call.in-map:
{recordEntityName:recordEntity,
                        recordId:recordId, subject:title, body:noteText, contentType:noteContentType, mentionPartyIds:mentionPartyIds,
                        recordUrl:recordLinkOut.url}

else.script:
// a page name has letters, digits and .,'-_:()!? only; a name in use gets the time added
const fromText = String(noteText).split('\n').map((line) => line.replace(/^#+\s*/, '').trim()).find((line) => line) || ''
let name = String(title || fromText.substring(0, 60)).replace(/[^\w\.\-,':()!\? ]+/g, ' ').replace(/\s+/g, ' ').trim()
if (!name) name = ec.l10n.localize('Note')
const inUse = (pageName) => ec.entity.find('moqui.resource.wiki.WikiPage').condition('wikiSpaceId', wikiSpaceId)
        .condition('pagePath', pageName).disableAuthz().count() > 0
if (inUse(name)) name = name + ' (' + ec.l10n.format(ec.user.nowTimestamp, 'yyyy-MM-dd HH.mm.ss') + ')'
pageName = name

actions.script:
const isOrg = partyTypeEnumId === 'PtyOrganization'
const name = String(contactName).trim().replace(/\s+/g, ' ')
const space = name.lastIndexOf(' ')
contact = {partyTypeEnumId: isOrg ? 'PtyOrganization' : 'PtyPerson'}
if (isOrg) contact.organizationName = name
else if (space > 0) { contact.firstName = name.substring(0, space); contact.lastName = name.substring(space + 1) }
else contact.firstName = name
if (!isOrg && organizationPartyId) contact.organizationPartyId = organizationPartyId
let digits = phone ? String(phone).replace(/\D/g, '') : ''
phoneParts = null
if (digits) {
    let countryCode = null
    if (digits.length === 11 && digits.startsWith('1')) { countryCode = '1'; digits = digits.substring(1) }
    phoneParts = digits.length === 10 ? {countryCode: countryCode, areaCode: digits.substring(0, 3), contactNumber: digits.substring(3, 6) + '-' + digits.substring(6)}
            : {countryCode: countryCode, areaCode: null, contactNumber: digits}
}
if (emailAddress) contact.emails = [{emailAddress: String(emailAddress).trim(), contactMechPurposeId: 'EmailPrimary'}]
if (phoneParts) contact.phones = [Object.assign({contactMechPurposeId: 'PhonePrimary'}, phoneParts)]
isDirectory = contactBookId === 'DIRECTORY'
